steps.command:
set -euo pipefail; cd interface; npm audit --json >/tmp/matrixhub-final-audit.json || true; npm audit --omit=dev --json >/tmp/matrixhub-final-prod-audit.json || true; python3 - <<'PY'
import json,sys
for label,path in [('ALL','/tmp/matrixhub-final-audit.json'),('PROD','/tmp/matrixhub-final-prod-audit.json')]:
 d=json.load(open(path)); v=d.get('metadata',{}).get('vulnerabilities',{}); print(label, json.dumps(v, sort_keys=True));
 if v.get('total',0):
  for name,item in sorted(d.get('vulnerabilities',{}).items()): print(label, name, item.get('severity'), item.get('range'), item.get('fixAvailable'))
  sys.exit(2)
PY
